class UlusJobQueue(JobQueue):
    """Zamanlanmış işler, kuyruğun ait olduğu botun adına çalışır (bir klonun güncellemesi sırasında
    kurulan zamanlayıcı yüzünden ana botun işleri klon bağlamına kaymasın)."""
    @staticmethod
    async def job_callback(job_queue, job) -> None:
        _ctx_bot.set(job_queue.application.bot)  # her iş kendi görevinde çalışır; ayar sadece o işe özel
        await job.run(job_queue.application)

_main_absent_checked: dict = {}

async def _main_bot_absent(cid: str, via) -> bool:
    """Ana bot bu grupta değil mi? (klonun gözünden, sohbet başına 1 saatte bir kontrol)"""
    if time.time() - _main_absent_checked.get(cid, 0) < 3600:
        return False
    _main_absent_checked[cid] = time.time()
    try:
        m = await via.get_chat_member(cid, BOT_ID)
    except TelegramError:
        return True
    except Exception:
        return False
    return getattr(m, 'status', 'left') in ('left', 'kicked')

# Kişi hedefleyen komutlar (Türkçe asıl adlarıyla; İngilizce eş adlar canon_cmd ile buna döner)
TARGET_CMDS = {'addadmin', 'remove', 'ban', 'unban', 'kick', 'mute', 'unmute', 'warn', 'unwarn', 'warns', 'klasorcu',
               'sicil', 'whitelist', 'profil', 'info', 'admin', 'basadmin', 'yardimcikurucu', 'uyeetiketi',
               'engelle', 'engelkaldir', 'gban', 'ungban'}

def _mention_to_id(msg) -> None:
    """Yönetici @ yazıp listeden kişiyi seçince Telegram mesaja kişinin ID'sini gömer (text_mention).
    Bot o kişiyi hiç görmemiş olsa da tanınsın diye hedef komutlarda bu kısım ID ile değiştirilir:
    '/admin Ali Veli yardımcı' → '/admin 123456 yardımcı'."""
    if not isinstance(getattr(msg, 'text', None), str) or not msg.text.startswith('/') or not hasattr(msg, '_unfrozen'):
        return
    ents = [e for e in (msg.entities or ()) if e.type == 'text_mention' and e.user]
    if not ents or canon_cmd(msg) not in TARGET_CMDS:
        return
    raw = msg.text.encode('utf-16-le')  # Telegram konumları UTF-16 birimiyle verir
    for e in sorted(ents, key=lambda x: x.offset, reverse=True):
        raw = raw[:e.offset * 2] + str(e.user.id).encode('utf-16-le') + raw[(e.offset + e.length) * 2:]
    with msg._unfrozen():
        msg.text = raw.decode('utf-16-le')
        msg.entities = tuple(e for e in (msg.entities or ()) if e.type == 'bot_command' and e.offset == 0)

async def bot_context_handler(update: Update, context):
    """Her güncellemenin en başında: hangi botla çalışıldığını işaretler; başka botumuzun yönettiği sohbetin
    güncellemelerini (aynı grupta iki botumuz varsa çift işlem olmasın diye) yok sayar."""
    _ctx_bot.set(context.bot)
    PERF['updates'] += 1
    _mention_to_id(getattr(update, 'message', None))
    if getattr(update, 'callback_query', None) is not None:
        note_callback_lang(update)
    chat = update.effective_chat
    if chat and chat.type == 'private':
        note_private_user(context.bot.id, update)
    if not chat or chat.type == 'private' or update.my_chat_member:
        return
    cid = str(chat.id)
    if cid not in _chat_bot_map:
        chat_bot_id(cid)
    raw = _chat_bot_map.get(cid)
    if raw is None:
        return
    if raw == -1:  # sahipsiz kalmış sohbet: ilk gelen botumuz sahiplenir
        set_chat_bot(cid, context.bot.id)
        return
    if raw == 0 and BOT_ID and context.bot.id != BOT_ID and await _main_bot_absent(cid, context.bot):
        # eski sürümde ayar kaydı bot_id'yi siliyordu: ana botun olmadığı bu grubu klon geri sahiplenir
        set_chat_bot(cid, context.bot.id)
        return
    owner = raw or BOT_ID
    if owner != context.bot.id and owner in RUNNING_BOTS:
        raise ApplicationHandlerStop


_db_lock = asyncio.Lock()


_db_local = threading.local()  # iş parçacığı başına tek, kalıcı bağlantı


def _sql_mybot(bot_id) -> int:
    """SQL: mybot(channels.bot_id) — sohbet şu an çalışan bota mı ait (ana bot: NULL/0/-1/kendi ID'si)."""
    cur = cur_bot_id()
    if cur == BOT_ID or not cur:
        return int(bot_id in (None, 0, -1, BOT_ID))
    return int(bot_id == cur)

def get_db():
    """Kalıcı bağlantı (her sorguda yeniden açılmaz). `with get_db() as conn:` bloğu bitince commit/rollback yapar,
    bağlantı açık kalır. Bloklar içinde await yok; eşzamanlı işlemede işlemler birbirine karışmaz."""
    conn = getattr(_db_local, 'conn', None)
    if conn is None or _db_local.path != DB_FILE:
        if conn is not None:
            try:
                conn.close()
            except sqlite3.Error:
                pass
        conn = sqlite3.connect(DB_FILE, timeout=30, check_same_thread=False)
        conn.row_factory = sqlite3.Row
        conn.create_function('mybot', 1, _sql_mybot, deterministic=False)  # bu botun sohbeti mi? (klon filtreleri)
        conn.execute("PRAGMA busy_timeout = 30000")
        conn.execute("PRAGMA synchronous = NORMAL")
        conn.execute("PRAGMA temp_store = MEMORY")
        conn.execute("PRAGMA cache_size = -16000")  # ~16 MB sayfa önbelleği
        _db_local.conn, _db_local.path = conn, DB_FILE
    return conn

